# -*- coding: utf-8 -*-
# GENERATED BY AI
"""Connector pinout rendering from KiCad footprints.

Derives a 2D pinout drawing of a connector (not the footprint on the PCB)
from a KiCad footprint (``.kicad_mod`` file, e.g. from a ``.pretty``
footprint library): the pads define the pin positions and sizes, and the
drawing shows the connector housing, one pin per numbered pad (pin 1 with
a thicker outline), mounting holes, and the pin numbers. Used by the
connector ``footprint`` attribute; see ``docs/syntax.md``.

Parsing relies on the ``kiutils`` package (https://github.com/mvnmgrx/kiutils).
"""

import hashlib
import math
import tempfile
from pathlib import Path
from typing import Dict, List, Tuple

from kiutils.footprint import Footprint

# Colors used when drawing the connector pinout (on a light background)
COLOR_HOUSING = "#e9e9e9"  # connector housing body
COLOR_HOUSING_OUTLINE = "#333333"  # connector housing outline
COLOR_PIN = "#c8c8c8"  # connector pins
COLOR_PIN_OUTLINE = "#555555"  # pin outline
COLOR_PIN1_OUTLINE = "#111111"  # outline of pin 1
COLOR_NUMBER = "#333333"  # pin numbers
COLOR_HOLE = "#ffffff"  # mounting holes
COLOR_HOLE_OUTLINE = "#555555"  # mounting hole outline

HOUSING_MARGIN = 0.3  # fraction of the largest pin size added around the pins
MIN_HOUSING_MARGIN = 0.5  # mm, lower bound for the housing margin
HOUSING_CORNER = 0.5  # mm housing corner radius
HOUSING_OUTLINE_WIDTH = 0.12  # mm
PIN_OUTLINE_WIDTH = 0.1  # mm
PIN1_OUTLINE_WIDTH = 0.25  # mm, thicker outline marks pin 1
DEFAULT_PAD_ROUNDRECT_RATIO = 0.25
DEFAULT_IMAGE_WIDTH = 200  # points, like WireViz image width attribute
MARGIN = 0.25  # mm between housing and SVG border
MIN_FONT_SIZE = 0.5  # mm, below this pin numbers are drawn outside the pin
OUTSIDE_FONT_SIZE = 0.8  # mm, pin numbers drawn outside the pin

# Keys allowed in the YAML footprint attribute
FOOTPRINT_ATTRIBUTE_KEYS = {"library", "part", "width", "height", "bgcolor", "caption"}


def _fmt(value: float) -> str:
    """Format a float without trailing zeros for use in SVG output."""
    return f"{value:.4f}".rstrip("0").rstrip(".") or "0"


def _escape(text: str) -> str:
    """Escape a string for use in SVG text content."""
    return (
        str(text)
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
    )


class _Renderer:
    """Collects SVG fragments and the bounding box while walking the pads."""

    def __init__(self, footprint: Footprint):
        self.footprint = footprint
        self.min_x = math.inf
        self.min_y = math.inf
        self.max_x = -math.inf
        self.max_y = -math.inf
        self.holes: List[str] = []
        self.pins: List[str] = []
        self.pin_numbers: List[str] = []

    # -- bounding box ------------------------------------------------------

    def _track(self, x: float, y: float) -> None:
        self.min_x = min(self.min_x, x)
        self.min_y = min(self.min_y, y)
        self.max_x = max(self.max_x, x)
        self.max_y = max(self.max_y, y)

    # -- pads --------------------------------------------------------------

    def _pad(self, pad) -> None:
        position = pad.position
        w, h = float(pad.size.X), float(pad.size.Y)
        angle = float(position.angle) if position.angle is not None else 0
        numbered = bool(pad.number) and pad.number != "~"

        # Track bounding box (rotated extent of the pad)
        half_x, half_y = self._pad_extent(pad, w, h, angle)
        self._track(position.X - half_x, position.Y - half_y)
        self._track(position.X + half_x, position.Y + half_y)

        if not numbered:
            # Mechanical pad: drawn as a mounting hole
            self.holes.append(self._mounting_hole(pad, position))
            return

        half = max(half_x, half_y)

        group = [
            f'<g transform="translate({_fmt(position.X)} {_fmt(position.Y)}) '
            f'rotate({_fmt(-angle)})">'
        ]
        group.append(self._pin_shape(pad, w, h))
        if pad.drill is not None and pad.drill.diameter:
            group.append(self._pin_drill(pad))
        group.append("</g>")
        self.pins.append("".join(group))

        self._pad_number(pad, position, w, h, half)

    @staticmethod
    def _pad_extent(pad, w: float, h: float, angle_deg: float) -> Tuple[float, float]:
        """Return the half extents (x, y) of a pad, including its rotation."""
        if pad.shape == "circle":
            radius = max(w, h) / 2
            return radius, radius
        angle = math.radians(angle_deg)
        cos_a, sin_a = abs(math.cos(angle)), abs(math.sin(angle))
        return (
            (w * cos_a + h * sin_a) / 2,
            (w * sin_a + h * cos_a) / 2,
        )

    def _pin_outline(self, pad) -> Tuple[str, float]:
        """Return the outline color and width for a pin, marking pin 1."""
        if str(pad.number) == "1":
            return COLOR_PIN1_OUTLINE, PIN1_OUTLINE_WIDTH
        return COLOR_PIN_OUTLINE, PIN_OUTLINE_WIDTH

    def _pin_shape(self, pad, w: float, h: float) -> str:
        outline, width = self._pin_outline(pad)
        shape = pad.shape
        if shape == "circle":
            return (
                f'<circle cx="0" cy="0" r="{_fmt(max(w, h) / 2)}" '
                f'fill="{COLOR_PIN}" stroke="{outline}" '
                f'stroke-width="{_fmt(width)}"/>'
            )
        if shape == "oval":  # stadium shape
            return self._pin_rect(w, h, min(w, h) / 2, outline, width)
        if shape == "roundrect":
            ratio = (
                pad.roundrectRatio
                if pad.roundrectRatio is not None
                else DEFAULT_PAD_ROUNDRECT_RATIO
            )
            radius = min(w, h) / 2 * float(ratio)
            return self._pin_rect(w, h, radius, outline, width)
        if shape == "custom":
            parts = [self._custom_pad_anchor(pad, w, h, outline, width)]
            parts.extend(self._custom_pad_primitives(pad))
            return "".join(parts)
        # rect and trapezoid (rect_delta is not exposed by kiutils and is
        # deprecated by KiCad, so trapezoid pads are drawn as rectangles)
        return self._pin_rect(w, h, 0, outline, width)

    @staticmethod
    def _pin_rect(w: float, h: float, radius: float, outline: str, width: float) -> str:
        rounded = f' rx="{_fmt(radius)}"' if radius else ""
        return (
            f'<rect x="{_fmt(-w / 2)}" y="{_fmt(-h / 2)}" width="{_fmt(w)}" '
            f'height="{_fmt(h)}"{rounded} fill="{COLOR_PIN}" '
            f'stroke="{outline}" stroke-width="{_fmt(width)}"/>'
        )

    def _custom_pad_anchor(self, pad, w: float, h: float, outline: str, width: float) -> str:
        anchor = (
            pad.customPadOptions.anchor
            if pad.customPadOptions is not None
            else "rect"
        )
        if anchor == "circle":
            return (
                f'<circle cx="0" cy="0" r="{_fmt(max(w, h) / 2)}" '
                f'fill="{COLOR_PIN}" stroke="{outline}" '
                f'stroke-width="{_fmt(width)}"/>'
            )
        return self._pin_rect(w, h, 0, outline, width)

    @staticmethod
    def _custom_pad_primitives(pad) -> List[str]:
        parts = []
        for primitive in pad.customPadPrimitives:
            coordinates = getattr(primitive, "coordinates", None)
            if coordinates:  # polygon primitives
                points = " ".join(f"{_fmt(p.X)},{_fmt(p.Y)}" for p in coordinates)
                parts.append(f'<polygon points="{points}" fill="{COLOR_PIN}"/>')
            # other custom pad primitive types are not drawn
        return parts

    def _pin_drill(self, pad) -> str:
        """Draw the hole of a plated pin (a round or slotted contact)."""
        drill = pad.drill
        offset = drill.offset
        cx = _fmt(offset.X) if offset is not None else "0"
        cy = _fmt(offset.Y) if offset is not None else "0"
        if drill.oval and drill.width:
            return (
                f'<ellipse cx="{cx}" cy="{cy}" rx="{_fmt(drill.diameter / 2)}" '
                f'ry="{_fmt(drill.width / 2)}" fill="{COLOR_HOLE}"/>'
            )
        return (
            f'<circle cx="{cx}" cy="{cy}" r="{_fmt(drill.diameter / 2)}" '
            f'fill="{COLOR_HOLE}"/>'
        )

    def _mounting_hole(self, pad, position) -> str:
        """Draw a mechanical pad as a mounting hole."""
        w, h = float(pad.size.X), float(pad.size.Y)
        drill = pad.drill
        if drill is not None and drill.diameter:
            if drill.oval and drill.width:
                body = (
                    f'<ellipse cx="{_fmt(position.X)}" cy="{_fmt(position.Y)}" '
                    f'rx="{_fmt(drill.diameter / 2)}" ry="{_fmt(drill.width / 2)}"'
                )
            else:
                body = (
                    f'<circle cx="{_fmt(position.X)}" cy="{_fmt(position.Y)}" '
                    f'r="{_fmt(drill.diameter / 2)}"'
                )
        else:
            body = (
                f'<circle cx="{_fmt(position.X)}" cy="{_fmt(position.Y)}" '
                f'r="{_fmt(min(w, h) / 2)}"'
            )
        return (
            f'{body} fill="{COLOR_HOLE}" stroke="{COLOR_HOLE_OUTLINE}" '
            f'stroke-width="{_fmt(PIN_OUTLINE_WIDTH)}"/>'
        )

    def _pad_number(self, pad, position, w: float, h: float, half: float) -> None:
        font_size = min(0.8 * min(w, h), 1.27)  # mm, capped like KiCad text
        if font_size >= MIN_FONT_SIZE:
            x, y, anchor = position.X, position.Y, "central"
        else:
            # pad too small: draw the number just above the pin
            x, y = position.X, position.Y - half - 0.3
            font_size, anchor = OUTSIDE_FONT_SIZE, "baseline"
        self.pin_numbers.append(
            f'<text x="{_fmt(x)}" y="{_fmt(y)}" '
            f'font-family="sans-serif" font-size="{_fmt(font_size)}" '
            f'fill="{COLOR_NUMBER}" text-anchor="middle" '
            f'dominant-baseline="{anchor}">'
            f"{_escape(pad.number)}</text>"
        )

    # -- assembly ----------------------------------------------------------

    def run(self) -> Tuple[str, float, float]:
        for pad in self.footprint.pads:
            self._pad(pad)

        if self.min_x is math.inf:  # footprint without pads
            self.min_x = self.min_y = -1.0
            self.max_x = self.max_y = 1.0

        largest_pin = max(
            (max(float(p.size.X), float(p.size.Y)) for p in self.footprint.pads),
            default=1.0,
        )
        housing_margin = max(MIN_HOUSING_MARGIN, HOUSING_MARGIN * largest_pin)
        housing_margin += PIN1_OUTLINE_WIDTH / 2  # keep pin 1 outline inside

        hx0, hy0 = self.min_x - housing_margin, self.min_y - housing_margin
        hx1, hy1 = self.max_x + housing_margin, self.max_y + housing_margin
        housing_w, housing_h = hx1 - hx0, hy1 - hy0

        min_x, min_y = hx0 - MARGIN, hy0 - MARGIN
        width, height = housing_w + 2 * MARGIN, housing_h + 2 * MARGIN

        svg = [
            f'<svg xmlns="http://www.w3.org/2000/svg" width="{_fmt(width)}mm" '
            f'height="{_fmt(height)}mm" viewBox="{_fmt(min_x)} {_fmt(min_y)} '
            f'{_fmt(width)} {_fmt(height)}">',
            f'<rect x="{_fmt(hx0)}" y="{_fmt(hy0)}" width="{_fmt(housing_w)}" '
            f'height="{_fmt(housing_h)}" rx="{_fmt(HOUSING_CORNER)}" '
            f'fill="{COLOR_HOUSING}" stroke="{COLOR_HOUSING_OUTLINE}" '
            f'stroke-width="{_fmt(HOUSING_OUTLINE_WIDTH)}"/>',
            *self.holes,
            *self.pins,
            *self.pin_numbers,
            "</svg>",
        ]
        return "".join(svg), width, height


def render_footprint_svg(footprint: Footprint) -> Tuple[str, float, float]:
    """Draw a connector pinout from a KiCad footprint (parsed by kiutils).

    Returns the SVG document as a string, plus its width and height in mm.
    """
    return _Renderer(footprint).run()


def footprint_image(spec: Dict):
    """Create a WireViz Image with a connector pinout from a KiCad footprint.

    ``spec`` is the value of the connector ``footprint`` attribute:
    a dict with a ``library`` (path to a ``.pretty`` footprint library
    directory or directly to a ``.kicad_mod`` file), optionally a ``part``
    (footprint name within the library), and optional ``width``, ``height``,
    ``bgcolor``, and ``caption`` for the resulting image.
    """
    from wireviz.DataClasses import Image  # imported here to avoid circular imports

    unknown = set(spec) - FOOTPRINT_ATTRIBUTE_KEYS
    if unknown:
        raise ValueError(
            f"Unknown footprint attribute(s): {', '.join(sorted(unknown))}"
        )

    library = spec.get("library")
    part = spec.get("part")
    if not library:
        raise ValueError("The footprint attribute requires a 'library'")
    library_path = Path(str(library))
    footprint_file = library_path
    if footprint_file.suffix != ".kicad_mod":
        if not part:
            raise ValueError(
                "The footprint attribute requires a 'part' when 'library' "
                "is a footprint library directory"
            )
        footprint_file = library_path / f"{part}.kicad_mod"
    if not footprint_file.is_file():
        raise FileNotFoundError(
            f"KiCad footprint not found: {footprint_file}"
        )

    footprint = Footprint.from_file(str(footprint_file))
    svg, width_mm, height_mm = render_footprint_svg(footprint)

    # Cache the rendered SVG, one file per unique rendering
    cache_dir = Path(tempfile.gettempdir()) / "wireviz-footprints"
    cache_dir.mkdir(parents=True, exist_ok=True)
    digest = hashlib.sha256(svg.encode("utf-8")).hexdigest()[:8]
    svg_file = cache_dir / f"{footprint_file.stem}-{digest}.svg"
    if not svg_file.exists():
        svg_file.write_text(svg, encoding="utf-8")

    width = spec.get("width") or DEFAULT_IMAGE_WIDTH
    height = spec.get("height") or round(width * height_mm / width_mm)
    return Image(
        src=str(svg_file),
        width=int(width),
        height=int(height),
        bgcolor=spec.get("bgcolor"),
        caption=spec.get("caption"),
    )
